1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Damage = {
9	  itemType: string;
10	  amount: number;
11	};
12	
13	export type Step =
14	  | { op: "quote"; items: Item[] }
15	  | { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };
16	
17	export type Customer = { yearsWithMHPCO: number };
18	
19	export type Scenario = {
20	  customer: Customer;
21	  steps: Step[];
22	};
23	
24	export type Result = { premium: number } | { payout: number; remainingCap: number };
25	
26	const PROCESSING_FEE = 5;
27	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
28	const CURSE_SURCHARGE_RATE = 0.5;
29	const HIGH_ENCHANTMENT_THRESHOLD = 5;
30	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
31	const LOYALTY_YEARS_THRESHOLD = 2;
32	const LOYALTY_DISCOUNT_RATE = 0.2;
33	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
34	
35	const BASE_PREMIUMS: Record<string, number> = {
36	  sword: 100,
37	  amulet: 60,
38	  staff: 80,
39	  potion: 40,
40	  rune: 25,
41	  moonstone: 25,
42	};
43	
44	const INSURANCE_VALUES: Record<string, number> = {
45	  sword: 1000,
46	  amulet: 600,
47	  staff: 800,
48	  potion: 400,
49	  rune: 250,
50	  moonstone: 250,
51	};
52	
53	const DEDUCTIBLE_PER_DAMAGE = 100;
54	const HALF_REIMBURSEMENT_ENCHANTMENT = 8;
55	const HALF_REIMBURSEMENT_RATE = 0.5;
56	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
57	
58	const BLOCK_SIZE = 3;
59	const BLOCK_PREMIUM = 60;
60	
61	/** Items that share the same `type`, and so are priced together. */
62	type AlikeItems = Item[];
63	
64	const groupAlikeItems = (items: Item[]): AlikeItems[] => {
65	  const byType = new Map<string, AlikeItems>();
66	  items.forEach((item) => byType.set(item.type, [...(byType.get(item.type) ?? []), item]));
67	  return [...byType.values()];
68	};
69	
70	const formsBlock = (items: AlikeItems): boolean => items.length === BLOCK_SIZE;
71	
72	const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
73	
74	const alikeItemsBasePremium = (alikeItems: AlikeItems): number =>
75	  formsBlock(alikeItems)
76	    ? BLOCK_PREMIUM
77	    : alikeItems.reduce((total, item) => total + itemBasePremium(item), 0);
78	
79	const totalBasePremium = (items: Item[]): number =>
80	  groupAlikeItems(items).reduce((total, alikeItems) => total + alikeItemsBasePremium(alikeItems), 0);
81	
82	const isCursed = (item: Item): boolean => item.cursed === true;
83	
84	const isHighlyEnchanted = (item: Item): boolean =>
85	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
86	
87	/**
88	 * An additive rate rule: contributes `rate` × some base premium, but only to
89	 * subjects the rule `applies` to. Every rule is an independent additive term —
90	 * nothing compounds onto a running total — so a discount is simply a negative
91	 * `rate` rather than a subtraction applied at some point in a sequence.
92	 */
93	type RateRule<Subject> = { applies: (subject: Subject) => boolean; rate: number };
94	
95	/**
96	 * The combined rate of every rule that applies to `subject`. Callers multiply
97	 * this by the relevant base premium once, which keeps each rule additive.
98	 */
99	const combinedRate = <Subject>(rules: RateRule<Subject>[], subject: Subject): number =>
100	  rules.filter(({ applies }) => applies(subject)).reduce((total, { rate }) => total + rate, 0);
101	
102	/** Charged on each cursed/enchanted item's own base premium, not the policy's. */
103	const ITEM_SURCHARGES: RateRule<Item>[] = [
104	  { applies: isCursed, rate: CURSE_SURCHARGE_RATE },
105	  { applies: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
106	];
107	
108	const itemSurcharge = (item: Item): number =>
109	  itemBasePremium(item) * combinedRate(ITEM_SURCHARGES, item);
110	
111	const policySurcharges = (items: Item[]): number =>
112	  items.reduce((total, item) => total + itemSurcharge(item), 0);
113	
114	/** Everything a policy-wide rule may look at when deciding whether it applies. */
115	type Policy = { customer: Customer; priorContracts: number };
116	
117	const isLoyalCustomer = ({ customer }: Policy): boolean =>
118	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
119	
120	const isFollowUpContract = ({ priorContracts }: Policy): boolean => priorContracts > 0;
121	
122	/**
123	 * Charged once per quote on the policy's base premium.
124	 *
125	 * The unconditional first-insurance surcharge is deliberately not in this table:
126	 * see `FIRST_INSURANCE_SURCHARGE_RATE` at the quote site.
127	 */
128	const POLICY_ADJUSTMENTS: RateRule<Policy>[] = [
129	  { applies: isLoyalCustomer, rate: -LOYALTY_DISCOUNT_RATE },
130	  { applies: isFollowUpContract, rate: -FOLLOW_UP_DISCOUNT_RATE },
131	];
132	
133	const policyAdjustments = (policyBasePremium: number, policy: Policy): number =>
134	  policyBasePremium * combinedRate(POLICY_ADJUSTMENTS, policy);
135	
136	const quotePremium = (items: Item[], policy: Policy): number => {
137	  const policyBasePremium = totalBasePremium(items);
138	  // The first-insurance surcharge has no condition to test: the MHPCO treats
139	  // every item in a quote as newly insured, so it is charged on every quote,
140	  // including a long-standing customer's follow-up contract. That makes it a
141	  // fixed rate on the base — like PROCESSING_FEE is a fixed addend — rather
142	  // than a rule belonging in POLICY_ADJUSTMENTS.
143	  const firstInsuranceSurcharge = policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
144	  // Every term is added to the base, never multiplied onto a running total. The
145	  // algebraically equivalent base * (1 + rate) yields 110.00000000000001 for
146	  // base 100, which Math.ceil turns into a premium that is 1 G too high.
147	  return Math.ceil(
148	    policyBasePremium +
149	      policySurcharges(items) +
150	      firstInsuranceSurcharge +
151	      policyAdjustments(policyBasePremium, policy) +
152	      PROCESSING_FEE,
153	  );
154	};
155	
156	const isQuote = (step: Step): boolean => step.op === "quote";
157	
158	/**
159	 * A contract is created by each quote, so the number the customer already held
160	 * when `stepIndex` is reached is just the number of quotes before it. Claims are
161	 * not contracts and so do not count.
162	 */
163	const priorContractsAt = (steps: Step[], stepIndex: number): number =>
164	  steps.slice(0, stepIndex).filter(isQuote).length;
165	
166	const insuredItems = (steps: Step[], policyIndex: number): Item[] => {
167	  const step = steps[policyIndex];
168	  if (step?.op !== "quote") throw new Error(`Step ${policyIndex} did not create a policy`);
169	  return step.items;
170	};
171	
172	/**
173	 * The insured item a damage entry refers to. Matching is by `itemType` only —
174	 * a damage entry names a type, not a specific item, so with several alike items
175	 * on one policy the first match stands in for whichever was damaged.
176	 */
177	const damagedItem = (insured: Item[], damage: Damage): Item => {
178	  const item = insured.find(({ type }) => type === damage.itemType);
179	  if (!item) throw new Error(`Policy does not cover an item of type ${damage.itemType}`);
180	  return item;
181	};
182	
183	const insuranceSum = (items: Item[]): number =>
184	  items.reduce((total, item) => total + INSURANCE_VALUES[item.type], 0);
185	
186	/**
187	 * The reimbursable value of a damage before the deductible. Special clauses key
188	 * off the DAMAGED ITEM's own properties (material, enchantment), so this takes
189	 * the insured item rather than the damage entry alone.
190	 */
191	const reimbursedAmount = (damage: Damage, damagedItem: Item): number =>
192	  (damagedItem.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT
193	    ? damage.amount * HALF_REIMBURSEMENT_RATE
194	    : damage.amount;
195	
196	/** The deductible is charged per damaged item, not once per incident. */
197	const damagePayout = (damage: Damage, damagedItem: Item): number =>
198	  reimbursedAmount(damage, damagedItem) - DEDUCTIBLE_PER_DAMAGE;
199	
200	const incidentPayout = (damages: Damage[], insured: Item[]): number =>
201	  // Rounded down, in the MHPCO's favor. Applied to the incident total rather
202	  // than to each damage, so a single incident loses at most 1 G to rounding.
203	  Math.floor(
204	    damages.reduce((total, damage) => total + damagePayout(damage, damagedItem(insured, damage)), 0),
205	  );
206	
207	/** A policy pays out at most twice the insurance sum of the items it covers. */
208	const payoutCap = (items: Item[]): number =>
209	  insuranceSum(items) * CAP_MULTIPLE_OF_INSURANCE_SUM;
210	
211	const claimResult = (steps: Step[], policyIndex: number, damages: Damage[]) => {
212	  const insured = insuredItems(steps, policyIndex);
213	  const payout = incidentPayout(damages, insured);
214	  return { payout, remainingCap: payoutCap(insured) - payout };
215	};
216	
217	export const runScenario = (scenario: Scenario): Result[] =>
218	  scenario.steps.map((step, stepIndex) => {
219	    if (step.op === "quote") {
220	      const policy = {
221	        customer: scenario.customer,
222	        priorContracts: priorContractsAt(scenario.steps, stepIndex),
223	      };
224	      return { premium: quotePremium(step.items, policy) };
225	    }
226	    return claimResult(scenario.steps, step.policy, step.incident.damages);
227	  });
